<?php require 'inc.php';
if(post()){$l=(float)$_POST['l'];if($l>0){q('INSERT INTO delivery(member_id,recorded_by,delivery_date,delivery_time,litres) VALUES(?,?,CURDATE(),CURTIME(),?)',[$_POST['m'],$_SESSION['uid'],$l]);flash('Delivery recorded. It now waits for the quality test.');}}
start('Milk intake');?>
<div class="card"><form class="row" method="post"><div><label>Farmer</label><select name="m"><?=members_options()?></select></div><div><label>Litres</label><input name="l" type="number" step="0.1" min="0.1" required style="width:100px"></div><button>Record delivery</button></form></div>
<div class="card wrap"><table><tr><th>ID</th><th>Farmer</th><th>Date</th><th>Litres</th><th>Status</th></tr><?php foreach(q('SELECT d.*,m.full_name,t.result FROM delivery d JOIN member m USING(member_id) LEFT JOIN quality_test t USING(delivery_id) ORDER BY d.delivery_id DESC LIMIT 15') as $d)echo '<tr><td>'.$d['delivery_id'].'</td><td>'.e($d['full_name']).'</td><td>'.$d['delivery_date'].'</td><td>'.$d['litres'].'</td><td><span class="tag '.($d['result']=='Accepted'?'ok':($d['result']?'bad':'')).'">'.($d['result']?:'Pending test').'</span></td></tr>';?></table></div><?php done();
